INSERT INTO changelog (title, body, created_at) VALUES
('Задачі по кроках',
'Велика задача тепер — покрокова: кожен розділ «## …» в інструкції стає окремою вкладкою. Зліва (на телефоні — смужкою зверху): Огляд → Крок 1 → Крок 2 → … → Фініш. У кожному кроці — свої галочки прямо в тексті (клацаєш — зберігається), прогрес кроку, тексти для копіювання, кнопки «← назад», «✓ Крок виконано», «далі →». Огляд — суть, таблиця структури, карта кроків з прогресом, підзадачі, посилання. Фініш — що зроблено, що лишилось, і «Закрити зі звітом». Джері пише нові задачі вже так (окремий набір/форма/кампанія — окремий крок, дії — галочками). Стару велику задачу — кнопка «Джері, розклади по кроках» у вікні задачі. Джері бачить, скільки галочок відмічено в кожному кроці. Ще: у чаті з Джері Enter надсилає, Shift+Enter — новий рядок (на телефоні Enter — перенос, надсилає кнопка).',
'2026-11-02 12:00:00');
